shots.draw_js:
clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"频率派",sub:"造置信区间",state:"dead"},
  {label:"贝叶斯",sub:"维护后验",state:"on"}]});
note("换一整套语言",640,420,"y");
setCap("不再造置信区间，而是<b>维护一个分布</b>，用数据把它更新。");

clearScene();setEq(null);
setBig("α、β 是拟合出来的","每次重新拟合一遍分布");
setCap("不用拟合。它们就是<b>数出来的</b> —— 见过多少个 1，多少个 0。");

clearScene();setBig(null);
setEq("$$\\mathrm{Beta}(\\alpha,\\beta)\\ \\xrightarrow{\\ r=1\\ }\\ \\mathrm{Beta}(\\alpha{+}1,\\beta)\\qquad \\mathrm{Beta}(\\alpha,\\beta)\\ \\xrightarrow{\\ r=0\\ }\\ \\mathrm{Beta}(\\alpha,\\beta{+}1)$$","top");
note("α 数 1 的个数",420,340,"g lg");
note("β 数 0 的个数",880,340,"g lg");
setCap("<b>伪计数</b>：α 是「见过多少个 1」，β 是「见过多少个 0」。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"手术",sub:"Beta(4,2)",state:"on"},
  {label:"并指",sub:"Beta(3,3)",state:"on"},
  {label:"不处理",sub:"Beta(2,4)",state:"dead"},
  {label:"先验",sub:"都是 Beta(1,1)",state:"off"}]});
note("各观测四次之后",640,410,"sm");
setCap("从 Beta(1,1) 出发，各拉四次：<b>3胜1负 / 2胜2负 / 1胜3负</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"共轭",sub:"更新只改数",state:"on"},
  {label:"α β",sub:"是计数",state:"on"},
  {label:"β 这个字母",sub:"后半讲另指",state:"dead"}]});
note("记号会撞车",640,420,"r");
setCap("<b>指名反驳</b>：不用拟合，<b>共轭</b>让更新退化成<b>加一</b>。");

clearScene();setBig(null);setEq(null);
note("后验有了",640,290,"y lg");
note("拿它怎么选臂",640,370,"sm lg");
setCap("分布维护好了。但<b>选哪个臂</b>还是个没回答的问题。");

clearScene();setEq(null);
setBig("按后验均值比例选","均值高的多选一点，公平");
setCap("那又把<b>不确定性</b>扔了 —— Beta(4,2) 和 Beta(40,20) 均值一样。");

clearScene();setBig(null);
setEq("$$P(\\text{选 }a)\\ =\\ P\\big(a=\\arg\\max_{a'}\\theta_{a'}\\ \\big|\\ \\text{数据}\\big)$$","top");
note("以「它是最优臂」的概率选它",640,330,"g lg");
setCap("<b>概率匹配</b>：选某个臂的概率，等于它<b>确实是最优臂</b>的后验概率。");

clearScene();setBig(null);
setEq("$$P(a=\\arg\\max)=\\int\\!\\cdots\\!\\int \\mathbb{1}\\big[\\theta_a=\\max\\big]\\prod_{a'} p(\\theta_{a'})\\,d\\theta_{a'}$$","top");
note("m 个臂就是 m 重积分",640,330,"r lg");
setCap("要真算这个概率，得做一个 <b>m 维积分</b> —— 没有闭式。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"按均值比例",sub:"又扔了形状",state:"dead"},
  {label:"概率匹配",sub:"规则是对的",state:"on"},
  {label:"怎么算",sub:"m 维积分",state:"dead"}]});
note("正确 ≠ 可执行",640,420,"y");
setCap("<b>指名反驳</b>：不是按均值比例，是按<b>「它是最优臂」的概率</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"抽一组 θ",sub:"从后验",state:"on"},
  {label:"当成真的",sub:"不加权",state:"on"},
  {label:"贪心",sub:"取 argmax",state:"on"},
  {label:"更新",sub:"加一",state:"on"}]});
note("整个算法四步",640,410,"y");
setCap("那个积分<b>不用算</b>。Thompson 采样：抽一次样，当真，贪心。");

clearScene();setEq(null);
setBig("抽样只是近似那个积分","多抽几次估一估概率");
setCap("<b>不是近似</b>。抽一次就<b>精确地</b>实现了概率匹配。");

clearScene();setBig(null);setEq(null);
note("抽一组 θ，取 argmax",640,280,"y lg");
note("某个臂中选的概率",640,340,"sm lg");
note("= 它的 θ 恰好最大的概率",640,400,"g lg");
setCap("<b>按定义相等</b>：中选 ⟺ 它抽到的 θ 最大 ⟺ 它是（这次抽样下的）最优臂。");

clearScene();setBig(null);setEq(null);
morphBars({from:[0.6979,0.2404,0.0617],to:[0.6975,0.2398,0.0627],
  x:380,y:350,w:520,h:150,max:0.78,dur:1600,
  label:function(i){return ["手术","并指","不处理"][i];},
  cls:function(i){return "g";},
  fmt:function(v){return v.toFixed(4);}});
note("TS 频率 → 最优概率",640,392,"sm");
setCap("两组数字<b>逐位吻合</b>到小数点后三位 —— 剩下的是蒙特卡洛噪声。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[2.73,4.08,6.91,11.14],
  x:330,y:350,w:620,h:150,max:12.5,
  label:function(i){return ["200","10³","5×10³","2×10⁴"][i];},
  cls:function(i){return i===3?"g":"y";},
  fmt:function(v){return v.toFixed(2)+"×";}});
note("UCB 遗憾 ÷ TS 遗憾",640,392,"sm");
setCap("<b>指名反驳</b>：不是近似，是<b>恰好相等</b>。而且在这个实例上它<b>跑得更好</b>。");
